package com.jinloes.practice;
import java.util.*; import static org.assertj.core.api.Assertions.assertThat;
public final class ExampleRunner { private static final String USAGE="Input: a sorted integer array, for example: [1, 2, 3]"; private ExampleRunner(){} public static void main(String[] args){ if (args.length > 0) { runInput(String.join(" ", args).trim()); return; } assertThat(inorder(Solution.buildBalanced(new int[]{1,2,3}))).containsExactly(1,2,3); assertThat(Solution.buildBalanced(new int[0])).isNull(); assertThat(inorder(Solution.buildBalanced(new int[]{-2,0,5,9,12}))).containsExactly(-2,0,5,9,12); System.out.println("Examples passed: 3"); } private static void runInput(String input){ try{ System.out.println(inorder(Solution.buildBalanced(parse(input)))); }catch(RuntimeException e){ System.out.println(USAGE); } } static int[] parse(String t){ String c=t.replace('[',' ').replace(']',' ').replace(',',' ').trim(); if(c.isEmpty()) return new int[0]; return Arrays.stream(c.split("\\s+")).mapToInt(Integer::parseInt).toArray(); } static List<Integer> inorder(Solution.TreeNode n){ List<Integer> out=new ArrayList<>(); walk(n,out); return out; } static void walk(Solution.TreeNode n,List<Integer> out){ if(n!=null){walk(n.left,out);out.add(n.value);walk(n.right,out);} } }
